with open('radiograph.jpg', 'rb') as f:
    data = f.read()

import re
matches = re.findall(b'[\x20-\x7e]{4,}', data)
for m in matches:
    s = m.decode('ascii', errors='ignore')
    if any(k in s.lower() for k in ['sidexis', 'sirona', 'dentsply', 'pai', 'lesion', 'patient', 'study', 'date', 'http', 'doi', 'github']):
        print(s)
